const url = 'https://ai.google.dev/gemini-api/docs/url-context';
try {
  const res = await fetch(url, { redirect: 'follow' });
  const text = await res.text();
  nodeRepl.write(JSON.stringify({ ok: true, status: res.status, length: text.length, head: text.slice(0, 120), tail: text.slice(-120) }, null, 2));
} catch (err) {
  nodeRepl.write(JSON.stringify({ ok: false, error: String(err) }, null, 2));
}
